import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  Img,
  interpolate,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type PlaneWindowProps = Record<string, any>;

const PlaneWindow: React.FC<PlaneWindowProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 12,
  shutterColor = "#e8e8ea",
  windowFrameColor = "#d1d1d6",
  glassOpacity = 0.3,
  destinations = [
    "https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&q=80&w=1080", // Beach
    "https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?auto=format&fit=crop&q=80&w=1080", // City
    "https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&q=80&w=1080", // Mountains
    "https://images.unsplash.com/photo-1519501025264-65ba15a82390?auto=format&fit=crop&q=80&w=1080", // Night City
  ],
}) => {
  // No fonts strictly needed for visuals, but hook is kept for standard compliance
  useFontLoader([]); 

  const frame = useCurrentFrame();
  const { width, fps } = useVideoConfig();

  // --- Layout Calculations ---
  // Responsive window size roughly based on social media aspect ratios
  const windowWidth = width * 0.55;
  const windowHeight = width * 0.85; // Taller than wide
  const windowRadius = windowWidth * 0.35; // Squircle shape
  const frameThickness = width * 0.04;
  
  // --- Timing Logic ---
  const totalFrames = durationInSeconds * fps;
  const cycleCount = destinations.length > 0 ? destinations.length : 1;
  const framesPerCycle = totalFrames / cycleCount;
  
  // Determine current cycle and progress
  const currentCycleIndex = Math.floor(frame / framesPerCycle) % cycleCount;
  const frameInCycle = frame % framesPerCycle;
  
  // --- Shutter Animation ---
  // Cycle timeline: 
  // 0% - 15%: Open (Slide Up)
  // 15% - 85%: Hold Open
  // 85% - 100%: Close (Slide Down)
  
  const openDuration = framesPerCycle * 0.15;
  const closeStart = framesPerCycle * 0.85;
  
  // Interpolate shutter Y position (0% = Closed, -100% = Open)
  const shutterY = interpolate(
    frameInCycle,
    [0, openDuration, closeStart, framesPerCycle],
    [0, -100, -100, 0],
    {
      easing: Easing.bezier(0.42, 0, 0.58, 1), // smooth ease-in-out
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // --- Background Image Logic ---
  // Select active image based on cycle
  const currentImage = destinations.length > 0 ? destinations[currentCycleIndex] : null;
  
  // Subtle parallax/zoom effect on the outside view to simulate plane movement
  // Reset zoom for each cycle so it looks like a fresh view
  const bgScale = interpolate(
    frameInCycle,
    [0, framesPerCycle],
    [1.1, 1.2], 
    { extrapolateRight: "clamp" }
  );

  const bgTranslateY = interpolate(
    frameInCycle,
    [0, framesPerCycle],
    [0, 20], // Slight drift down
    { extrapolateRight: "clamp" }
  );

  // Background color handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
      
      {/* Wall & Window Structure */}
      <AbsoluteFill style={{ 
        justifyContent: "center", 
        alignItems: "center", 
        zIndex: 10 
      }}>
        <div
          style={{
            position: "relative",
            width: windowWidth,
            height: windowHeight,
            borderRadius: windowRadius,
            // Frame Rim only, Wall removed
            border: `${frameThickness}px solid ${windowFrameColor}`,
            overflow: "hidden", // Clips the shutter and glass reflection and image
            backgroundColor: "black", // Fallback for image loading
            boxShadow: "0 10px 30px rgba(0,0,0,0.2)", // Subtle shadow for the standalone window
          }}
        >
          {/* 1. Outside View Layer (Rendered INSIDE the window to clip it) */}
          <div style={{
            position: "absolute",
            inset: 0,
            zIndex: 0,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}>
            {currentImage && (
                <Img
                  src={currentImage}
                  style={{
                    width: "120%", // Slightly larger for parallax
                    height: "120%",
                    objectFit: "cover",
                    transform: `scale(${bgScale}) translateY(${bgTranslateY}px)`,
                    transition: "none",
                  }}
                />
            )}
          </div>

          {/* Inner Shadow for depth inside the frame */}
          <div 
            style={{
              position: "absolute",
              inset: 0,
              borderRadius: windowRadius * 0.8, // Approximation for inner radius
              boxShadow: "inset 10px 10px 30px rgba(0,0,0,0.2), inset -5px -5px 20px rgba(255,255,255,0.5)",
              zIndex: 20,
              pointerEvents: "none",
            }} 
          />

          {/* 3. The Shutter */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              backgroundColor: shutterColor,
              transform: `translateY(${shutterY}%)`,
              zIndex: 15,
              // Adding some texture/shading to the shutter
              background: `linear-gradient(to bottom, ${shutterColor} 0%, #dcdcdf 100%)`,
              boxShadow: "0px 10px 20px rgba(0,0,0,0.3)", // Shadow cast by shutter onto window
              transition: "none",
            }}
          >
            {/* Shutter handle details */}
            <div style={{
                position: "absolute",
                bottom: "10%",
                left: "50%",
                transform: "translateX(-50%)",
                width: "30%",
                height: 6,
                borderRadius: 4,
                backgroundColor: "#bbb",
                boxShadow: "inset 0 1px 2px rgba(0,0,0,0.2)"
            }}/>
          </div>

          {/* 4. Glass Reflection (Static overlay) */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              zIndex: 5, // Behind shutter, in front of image
              background: `linear-gradient(135deg, rgba(255,255,255,${glassOpacity}) 0%, rgba(255,255,255,0) 40%, rgba(255,255,255,0) 60%, rgba(255,255,255,${glassOpacity * 0.5}) 100%)`,
              pointerEvents: "none",
            }}
          />
          
          {/* Removed SVG noise filter layer to reduce rendering complexity and prevent timeouts */}

        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default PlaneWindow;